  KEY `fk_sales_customer` (`customer_key`),
  KEY `fk_sales_territory` (`territory_key`),
  CONSTRAINT `fk_sales_customer` FOREIGN KEY (`customer_key`) REFERENCES `dim_customer` (`customer_key`),
  CONSTRAINT `fk_sales_product` FOREIGN KEY (`product_key`) REFERENCES `dim_product` (`product_key`),
  CONSTRAINT `fk_sales_territory` FOREIGN KEY (`territory_key`) REFERENCES `dim_territory` (`territory_key`)
) ENGINE=InnoDB AUTO_INCREMENT=76290 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
